import express from 'express';
import path from 'path';
import { createServer as createViteServer } from 'vite';
import { GoogleGenAI } from '@google/genai';

const app = express();
const PORT = 3000;

app.use(express.json());

// Lazy GoogleGenAI initialization
let aiClient: GoogleGenAI | null = null;
function getAI(): GoogleGenAI | null {
  if (!aiClient && process.env.GEMINI_API_KEY) {
    aiClient = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
  }
  return aiClient;
}

// Health check endpoint
app.get('/api/health', (req, res) => {
  res.json({ status: 'ok', time: new Date().toISOString() });
});

// AI Professional Offer Description Endpoint
app.post('/api/ai-summarize-quote', async (req, res) => {
  try {
    const { deviceName, brand, capacityKw, roomName, areaM2, clientName, marginPercent, totalGross } = req.body;

    const ai = getAI();
    if (!ai) {
      // Fallback response if GEMINI_API_KEY is not set
      return res.json({
        summary: `Profesjonalna oferta HVAC dla klienta ${clientName || 'Szanowny Kliencie'}. Zestaw oparty na cichym i wydajnym klimatyzatorze ${brand || 'Daikin'} ${deviceName || ''} o mocy ${capacityKw || 3.5} kW. Urządzenie idealnie dobrane do pomieszczenia ${roomName || 'docelowego'} (${areaM2 || 30} m²). Wycena obejmuje kompletny montaż, próżniowanie oraz uruchomienie z gwarancją producenta.`
      });
    }

    const prompt = `Jesteś doświadczonym inżynierem HVAC i doradcą technicznym. Wygeneruj zwięzły, niezwykle profesjonalny i przekonujący opis techniczny dla klienta końcowego (2-3 akapity), który zostanie dołączony do oficjalnej oferty cenowej.
Parametry oferty:
- Klient: ${clientName || 'Klient Indywidualny/Firma'}
- Pomieszczenie: ${roomName || 'Pomieszczenie główne'}, powierzchnia: ${areaM2 || 30} m²
- Urządzenie: ${brand} ${deviceName} (Moc chłodnicza: ${capacityKw} kW)
- Kwota oferty brutto: ${totalGross} PLN

Napisz w języku polskim. Skup się na korzyściach dla klienta: cicha praca, oszczędność energii, wysoka jakość montażu i gwarancja. Pisz profesjonalnie, bez zbędnego lania wody.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    const summaryText = response.text || 'Oferta dostosowana do najwyższych standardów HVAC.';
    return res.json({ summary: summaryText });
  } catch (error: any) {
    console.error('AI Quote Summary Error:', error);
    return res.status(500).json({ error: 'Nie udało się wygenerować opisu AI', details: error.message });
  }
});

// AI Technical Installation Advisor
app.post('/api/ai-technical-advice', async (req, res) => {
  try {
    const { query, deviceModel } = req.body;

    const ai = getAI();
    if (!ai) {
      return res.json({
        advice: `Standardowe zalecenia montażowe dla ${deviceModel || 'klimatyzatora Split'}: Zachowaj min. 15 cm odstępu od sufitu, użyj miedzi chłodniczej w otulinie kauczukowej, wykonaj próbę szczelności azotem (30-40 bar) oraz próżniowanie do min. 270 Pa.`
      });
    }

    const prompt = `Jesteś ekspertem technicznym ds. klimatyzacji i pomp ciepła. Odpowiedz zwięźle i konkretnie instalatorowi HVAC na pytanie dotyczące montażu/serwisu/doboru.
Model urządzenia: ${deviceModel || 'Ogólny układ Split'}
Pytanie instalatora: ${query}

Odpowiedz po polsku w punktach. Podaj konkretne wartości techniczne (średnice rur, ciśnienia, odległości, zasilanie, kody błędów) jeśli dotyczy.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return res.json({ advice: response.text });
  } catch (error: any) {
    console.error('AI Technical Advice Error:', error);
    return res.status(500).json({ error: 'Błąd doradcy technicznego AI' });
  }
});

async function startServer() {
  // Vite middleware in dev
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server KlimatPro B2B listening on http://0.0.0.0:${PORT}`);
  });
}

startServer();
